int main(){using namespace fps_detail;using namespace blocked_poly;std::mt19937 rng(1442027);const std::size_t page=sysconf(_SC_PAGESIZE);for(std::size_t n:{1,2,31,32,33,63,64,65,127,128,129,255,256,257,383,384,385,511,512,513,1023,1024,1025,65537,262144,262145,393217,500000})for(std::size_t input:{std::size_t(1),std::size_t(7),std::size_t(33),n/3+1,n,n+17}){std::size_t bytes=input*sizeof(Mint),readable=(bytes+page-1)/page*page;auto*base=static_cast<unsigned char*>(mmap(nullptr,readable+page,PROT_READ|PROT_WRITE,MAP_PRIVATE|MAP_ANONYMOUS,-1,0));require(base!=MAP_FAILED);auto*in=reinterpret_cast<Mint*>(base+readable-bytes);for(std::size_t i=0;i<input;++i)std::construct_at(in+i,Mint::word(2*Mint::mod()-1-rng()%1000));require(!mprotect(base,readable,PROT_READ));require(!mprotect(base+readable,page,PROT_NONE));std::vector<unsigned>words(std::min(input,n));for(std::size_t i=0;i<words.size();++i)words[i]=std::min(in[i].v,in[i].v-Mint::mod());std::vector<Mint>out(3,Mint(7));native_inverse(in,input,out,n);require(out.size()==n+3);for(int i=0;i<3;++i)require(out[i]==Mint(7));int lg=inverse_log(n);Arena arena(Transform::words(lg)+Arena::footprint(n)+Arena::footprint(inverse_scratch(n)));const Transform t(arena,lg);auto g=arena.take(n);inverse(t,words,g,arena.take(inverse_scratch(n)));for(std::size_t i=0;i<n;++i){auto expected=blocked_ntt::detail::multiply_mod(g[i],932051910);require(out[i+3].v==expected);}for(std::size_t i=0;i<words.size();++i)require(std::min(in[i].v,in[i].v-Mint::mod())==words[i]);require(!munmap(base,readable+page));}std::puts("fused inverse canonical exact/readonly/nopadding/short/prefix/boundaries: pass");}
